mapper.select:
SELECT * FROM sys_import_task WHERE tenant_id = #{tenantId} AND operator_id = #{operatorId}
AND biz_type IN #{type}
AND biz_type = #{bizType}
AND status = #{status}
ORDER BY task_id DESC

SELECT * FROM sys_import_task WHERE tenant_id = #{tenantId}
    AND status IN ('SUCCESS', 'PARTIAL', 'FAILED', 'CANCELLED', 'UPLOADED', 'VALIDATED')
    AND create_time < #{cutoff} ORDER BY task_id LIMIT 100

SELECT * FROM sys_import_task WHERE tenant_id = #{tenantId} AND task_id > #{afterId}
    AND status IN ('SUCCESS', 'PARTIAL') AND success_rows + fail_rows = total_rows
    AND file_url IS NOT NULL AND file_url NOT IN ('PENDING', 'REMOVED')
    AND biz_type IN #{type}
ORDER BY task_id LIMIT 100
